/**
 * Convert the subset of GitHub-flavored Markdown we emit into Slack "mrkdwn":
 * headings → bold, `**bold**` → `*bold*`, and `[text](url)` → `<url|text>`.
 */
function toSlackMrkdwn(md) {
    return md
        .replace(/^#{1,6}\s+(.*)$/gm, "*$1*")
        .replace(/\*\*(.+?)\*\*/g, "*$1*")
        .replace(/\[([^\]]+)\]\(([^)]+)\)/g, "<$2|$1>");
}
